
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_l06_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_l06", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.210367744813327e+02, 1.066150957519314e+02, 9.438576279385417e+01, 8.342284157057874e+01, 7.243082532415649e+01, 6.049299171662695e+01, 4.742258295517075e+01, 3.390705671204439e+01, 2.142832810613917e+01, 1.173122161620285e+01, 5.592025319109918e+00, 2.658301825039148e+00, 1.914529197523512e+00, 1.269949859900501e+00, 6.499201036164602e-01, 2.724980907587822e-01, 8.245858524805931e-02, 9.436008379609498e-03, 4.299403959654258e-04, 5.389663811142696e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


